#[inductive(combiner_go_to_collecting)]
fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
    // After this transition:
    // - combiner goes from Responding{..., idx == num_clients} to Collecting{elems: empty}

    // Prove not_waiting_inv
    assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies
        !post.slots.index(i)
    by {
        assert(pre.valid_idx(i));
        assert(pre.not_waiting_inv());
        // The transition doesn't change clients or slots
        assert(post.clients.index(i) === pre.clients.index(i));
        assert(post.slots.index(i) === pre.slots.index(i));
    }

    // Prove waiting_inv
    assert forall |i: nat| #[trigger] post.client_waiting(i) implies
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)
    by {
        assert(pre.valid_idx(i));
        assert(pre.waiting_inv());
        assert(post.clients.index(i) === pre.clients.index(i));

        // In the post state, combiner is Collecting with empty elems,
        // so combiner_has(i) is always false
        assert(post.combiner === Combiner::Collecting{ elems: Seq::empty() });
        assert(!post.combiner_has(i));

        // So we need either request_stored or response_stored
        assert(pre.client_waiting(i) ==> pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));

        // The transition doesn't change requests or responses
        assert(post.requests === pre.requests);
        assert(post.responses === pre.responses);
        assert(post.request_stored(i) === pre.request_stored(i));
        assert(post.response_stored(i) === pre.response_stored(i));

        // Since client_waiting is preserved and neither requests nor responses changed,
        // the property carries over
        assert(post.client_waiting(i) ==> post.request_stored(i) || post.response_stored(i));
    }

    // Prove request_stored_inv
    assert forall |i: nat| #[trigger] post.request_stored(i) implies
        post.client_waiting(i)
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && post.slots.index(i)
    by {
        assert(pre.request_stored_inv());
        // Transition doesn't change requests, clients, or slots
        assert(post.requests === pre.requests);
        assert(post.clients === pre.clients);
        assert(post.slots === pre.slots);
        assert(post.request_stored(i) === pre.request_stored(i));

        // Therefore the invariant carries over directly
        assert(pre.request_stored(i) ==> 
            pre.client_waiting(i)
            && pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid()
            && pre.slots.index(i));
    }

    // Prove response_stored_inv
    assert forall |i: nat| #[trigger] post.response_stored(i) implies
        post.client_waiting(i)
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && !post.slots.index(i)
    by {
        assert(pre.response_stored_inv());
        // Transition doesn't change responses, clients, or slots
        assert(post.responses === pre.responses);
        assert(post.clients === pre.clients);
        assert(post.slots === pre.slots);
        assert(post.response_stored(i) === pre.response_stored(i));

        // Therefore the invariant carries over directly
        assert(pre.response_stored(i) ==> 
            pre.client_waiting(i)
            && pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid()
            && !pre.slots.index(i));
    }
}

